export const articleSlugs: Record<string, string[]> = Object.fromEntries(
  Object.entries(articlesByLocale).map(([locale, articles]) => [
    locale,
    articles.map((article) => article.slug),
  ]),
);

export function getArticles(locale: string): ArticleInfo[] {
  return articlesByLocale[locale] || [];
}

export function getArticleBySlug(locale: string, slug: string): ArticleInfo | undefined {
  return getArticles(locale).find((article) => article.slug === slug);
}
